import fs from 'node:fs';import path from 'node:path';import {ROOT,readJSON} from '../src/core.mjs';
const report=readJSON(path.join(ROOT,'characters/orc-unarmed-front-review-data-v1.json'));
const labels={'orc-01-squire':'Golpe corpo a corpo','orc-01-archer':'Preparar e soltar disparo','orc-01-apprentice-mage':'Conjuração ofensiva','orc-01-acolyte':'Invocação de suporte','orc-01-rogue':'Estocada rápida','orc-01-scout':'Arremesso rápido','orc-01-brawler':'Soco de direita'};
const classes=readJSON(path.join(ROOT,'characters/orc-unarmed-front-review-data-v1.json')).classes;
const data={classes,counts:{Attack:5},durations:{Attack:90}},esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const html=`<!doctype html><html lang="pt-br"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Orc — ataque básico desarmado</title><style>:root{color-scheme:dark}body{font:16px system-ui;background:#20222a;color:#eee;margin:24px}p{line-height:1.5;max-width:1150px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}article{border:1px solid #666;border-radius:8px;padding:16px;overflow:auto}canvas,img.base{width:256px;height:256px;image-rendering:pixelated;background:repeating-conic-gradient(#555 0 25%,#373941 0 50%) 0/16px 16px}img.strip{image-rendering:pixelated;max-width:100%;background:#444}img.base{display:block}a{color:#9cf}button,select,input{font:inherit;padding:8px}nav{display:flex;gap:14px;flex-wrap:wrap;align-items:center;margin:20px 0}label{display:flex;gap:8px;align-items:center}details{margin-top:12px}.light{background:#efede7;color:#111}.light a{color:#056ca4}.light canvas,.light img.base{background:repeating-conic-gradient(#fff 0 25%,#ccc 0 50%) 0/16px 16px}output{font-variant-numeric:tabular-nums}[hidden]{display:none}</style><h1>Orc — ataque básico desarmado front_r</h1><p><strong>Um golpe físico comum nas oito roupas, incluindo Warrior.</strong> Primeiro lote front_r:30 quadros novos, seis fontes editáveis novas e dez quadros reutilizados de Warrior/Brawler. Os clipes de magia, arco e demais gestos anteriores foram preservados.</p><p>Este é o comando normal Atacar SEM arma: guarda, preparação, soco e recuperação; não é habilidade ou conjuração. Revise roupa, mão ativa, giro do tronco e continuidade. Warrior e Brawler reaproveitam as quatro vistas existentes; faltam90 quadros nas outras três vistas das seis roupas após esta revisão. Armas e integração Unity continuam pendentes.</p><nav><label>Animação <select id="state"><option>Attack</option></select></label><label>Classe <select id="classFilter"><option value="all">Todas</option>${classes.map(c=>`<option value="${c.id}">${esc(c.job)}</option>`).join('')}</select></label><button id="play">Pausar</button><button id="restart">Reiniciar</button><label><input id="repeat" type="checkbox" checked>Repetir prévia</label><label>Velocidade <select id="speed"><option value="0.5">0,5×</option><option value="1" selected>1×</option><option value="2">2×</option></select></label><label>Zoom <select id="zoom"><option value="1">1×</option><option value="2" selected>2×</option><option value="3">3×</option></select></label><button id="background">Trocar fundo</button><label>Quadro <input id="frame" type="range" min="0" max="4" value="0"><output id="counter">0/4</output></label></nav><p id="timing"></p><main>${classes.map(c=>`<article data-id="${c.id}"><h2>${esc(c.job)}</h2><p class="action">${esc(c.label)}</p><canvas width="128" height="128" id="canvas-${c.id}" aria-label="${esc(c.job)} combate front_r"></canvas><p>Revisão do golpe desarmado</p><details><summary>Base aprovada e fontes</summary><img class="base" src="${c.base}" alt="Base aprovada ${esc(c.job)}"><p><a class="editable" href="${c.clips.Attack.editable}">Fonte editável do clipe</a> · <a href="${c.id}/source/unarmed-front-v1-review.json">Verificação técnica</a></p><img class="strip" src="${c.clips.Attack.strip}" alt="Quadros ${esc(c.job)}"></details></article>`).join('')}</main><p><a href="orc-combat-front-validation-v1.json">Inventário e hashes</a> · <a href="orc-unarmed-front-validation-v1.json">Exportações reais no LibreSprite</a> · <a href="review-orc-basic-complete-v1.html">Baseline de cinco estados preservada</a></p><p>Esta prévia repete os clipes para revisão; os arquivos de combate estão marcados como ações únicas. Exportação final e integração Unity seguem pendentes.</p><script>
const data=${JSON.stringify(data)},images=new Map;let current='Attack',playing=true,started=performance.now(),held=0;window.orcCombatData=data;
function image(src){if(!images.has(src)){const i=new Image;i.src=src;images.set(src,i)}return images.get(src)}for(const c of data.classes)for(const clip of Object.values(c.clips))clip.frames.forEach(image);
function selectState(){current=document.querySelector('#state').value;held=0;started=performance.now();document.querySelector('#frame').max=data.counts[current]-1;document.querySelector('#timing').textContent=data.counts[current]+' quadros · '+(data.counts[current]*data.durations[current]/1000).toFixed(3)+' s a 1×';for(const c of data.classes){const a=document.querySelector('[data-id="'+c.id+'"]'),clip=c.clips[current];a.querySelector('.editable').href=clip.editable;a.querySelector('.strip').src=clip.strip;a.querySelector('.action').textContent=current==='Attack'?c.label:current==='Hit'?'Reação ao impacto':'Queda e derrota'}}
document.querySelector('#state').onchange=selectState;document.querySelector('#play').onclick=()=>{playing=!playing;started=performance.now()-held*data.durations[current]/Number(document.querySelector('#speed').value);document.querySelector('#play').textContent=playing?'Pausar':'Tocar'};document.querySelector('#restart').onclick=()=>{playing=true;held=0;started=performance.now();document.querySelector('#play').textContent='Pausar'};document.querySelector('#frame').oninput=e=>{playing=false;held=Number(e.target.value);document.querySelector('#play').textContent='Tocar'};document.querySelector('#speed').onchange=()=>{started=performance.now()-held*data.durations[current]/Number(document.querySelector('#speed').value)};document.querySelector('#classFilter').onchange=e=>{for(const a of document.querySelectorAll('article'))a.hidden=e.target.value!=='all'&&a.dataset.id!==e.target.value};document.querySelector('#background').onclick=()=>document.body.classList.toggle('light');document.querySelector('#zoom').onchange=e=>{for(const c of document.querySelectorAll('canvas,img.base'))c.style.width=c.style.height=128*Number(e.target.value)+'px'};
function tick(now){if(playing){const frame=Math.floor((now-started)*Number(document.querySelector('#speed').value)/data.durations[current]);held=document.querySelector('#repeat').checked?frame%data.counts[current]:Math.min(frame,data.counts[current]-1)}window.orcCombatFrame=held;document.querySelector('#counter').textContent=held+'/'+(data.counts[current]-1);document.querySelector('#frame').value=held;for(const c of data.classes){const ctx=document.querySelector('#canvas-'+c.id).getContext('2d'),i=image(c.clips[current].frames[held]);ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,128,128);if(i.complete&&i.naturalWidth)ctx.drawImage(i,0,0)}requestAnimationFrame(tick)}selectState();requestAnimationFrame(tick);</script></html>`;
fs.writeFileSync(path.join(ROOT,'characters/review-orc-unarmed-front-v1.html'),html);console.log('Unarmed front_r preview:40 frame references,8 outfits;30 new PNGs,6 new editables.');
